sql_calls.sql:
SELECT SUM(revenue_inr) as total_revenue
FROM store.daily_sales
WHERE date >= '2026-06-01' AND date <= '2026-06-30';

SELECT sku, name, price_inr, cost_inr
FROM store.products
WHERE sku IN ('BREAD-WHITE-400G', 'CURD-500G', 'MILK-FC-500ML', 'DAL-TOOR-1KG', 'SUGAR-1KG', 'ATTA-WW-5KG');

SELECT *
FROM payments.customer_complaints
WHERE complaint_ts >= '2026-06-01' AND complaint_ts < '2026-07-01';

SELECT snl.shipment_id, snl.sscc, snl.sku, snl.gtin, snl.cases, snl.units, snl.order_id, snl.line
FROM warehouse.shipping_notice_lines snl
WHERE snl.sscc = '029000010000010450';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'pos_lines';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'warehouse' AND table_name = 'shipments';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'fresh_deliveries';

SELECT * FROM store.fresh_deliveries
WHERE delivery_ts >= '2026-06-01' AND delivery_ts < '2026-07-01'
ORDER BY delivery_ts;

SELECT * FROM store.fresh_deliveries
WHERE delivery_ts >= '2026-06-16' AND delivery_ts < '2026-07-01'
ORDER BY delivery_ts;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'warehouse' AND table_name = 'shipping_notice_lines';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'store' AND table_name = 'daily_sales';

SELECT sku, name, pack, price_inr
FROM store.products
WHERE name ILIKE '%atta%' AND pack ILIKE '%5%kg%';

SELECT SUM(net_inr) as total_net_upi
FROM payments.upi_settlements
WHERE settlement_date >= '2026-06-01' AND settlement_date <= '2026-06-30';

SELECT DISTINCT till_status
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'store' AND table_name LIKE '%customer%';

SELECT COUNT(DISTINCT order_id) AS distinct_orders
FROM store.store_orders
WHERE order_date >= '2026-06-01' AND order_date < '2026-07-01';

SELECT COUNT(DISTINCT order_id) AS distinct_orders
FROM store.store_orders
WHERE created_ts >= '2026-06-01' AND created_ts < '2026-07-01';

SELECT sku, name, pack, price_inr, cost_inr, flow
FROM store.products
WHERE name ILIKE '%milk%' OR name ILIKE '%toned%';

SELECT sku, name, pack, price_inr, cost_inr
FROM store.products
WHERE name ILIKE '%atta%' OR name ILIKE '%wheat%';

SELECT refund_id, rrn, bill_id, amount_inr, trigger, requested_ts, completed_ts
FROM payments.upi_refunds
WHERE bill_id = 'B260601-040002';
